import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;

/** リクエストの中身を見てみるサンプル。 */
@WebServlet("/info")
public class InfoServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        res.getWriter().println("メソッド : " + req.getMethod());
        res.getWriter().println("パス     : " + req.getRequestURI());
        res.getWriter().println("クエリ   : " + req.getQueryString());
    }

    public static void main(String[] args) {
        // echoRequests() を付けると、どのリクエストの結果か分かりやすい
        MiniWeb.app().register(InfoServlet.class).echoRequests().serve();
    }
}

