import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;

@WebServlet("/pick")
public class PickServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        String[] colors = req.getParameterValues("color");
        if (colors == null) {
            // 無いときは null。空配列にしておくと、この後の処理を分けなくて済む
            colors = new String[0];
        }

        if (colors.length == 0) {
            res.getWriter().println("選択なし");
        } else {
            res.getWriter().println("選んだ色: " + String.join(", ", colors)
                    + " (" + colors.length + "件)");
        }
    }

    public static void main(String[] args) {
        MiniWeb.app().register(PickServlet.class).serve();
    }
}
